/* drawing helpers (VL_ prefix: no clash with engine globals) */
const VL_F='font-family="Nunito Sans, sans-serif"';
const VL_M='font-family="IBM Plex Mono, monospace"';
const VL_T=(x,y,t,o={})=>`<text x="${x}" y="${y}" ${o.mono?VL_M:VL_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}">${t}</text>`;
const VL_L=(x1,y1,x2,y2,col='#5C6577',w=2,ex='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const VL_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??12}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}" ${o.fo!=null?`fill-opacity="${o.fo}"`:''}/>`;
const VL_arrow=(x1,y1,x2,y2,col='#18213A',w=3)=>{const a=Math.atan2(y2-y1,x2-x1),h=14;return VL_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const VL_sb=(a,b)=>`${a}<tspan baseline-shift="sub" font-size="70%">${b}</tspan>`;
const VL_GR='#5C6577', VL_LG='#ADB5BD';
const VL_panel=(y,h,head)=>VL_box(14,y,612,h,{r:14})+VL_T(34,y+36,head,{fs:24,fw:700});
const VL_fa=(x,y,w,h,lab,col)=>VL_box(x,y,w,h,{st:col,sw:3,fill:'#FFFFFF'})+VL_T(x+w/2,y+h/2+9,lab,{fs:24,fw:800,a:'middle',fill:col});
/* a bit row: bits[] drawn in cells of width cw starting at x (leftmost = highest bit) */
const VL_bits=(x,y,bits,col,cw=64,o={})=>bits.map((b,i)=>b===''?'':VL_box(x+i*cw,y,cw-8,52,{st:col,sw:2.5,fill:o.fill||'#FFFFFF',r:8})+VL_T(x+i*cw+(cw-8)/2,y+37,b,{fs:30,fw:800,a:'middle',fill:col,mono:1})).join('');

